         values ($1, $2, $3, 'user', $4, $5, 'assistant_conversation', $6, $7, $8, 'synthetic-fixture', 'api')`,
        [
          crypto.randomUUID(),
          org,
          tx,
          ownerId,
          user ? "assistant_conversation.message_posted" : "assistant_conversation.reply_recorded",
