/** The outcome of the ADR-0051 §4 decision for an item the caller can see exists (rule 1 passed). */
export interface EvidenceReadDecision {
  readonly target: ResolvedTarget;
  readonly row: EvidenceRow;
  /** null: admitted; "item": refused by rule 2; "parent": refused by rule 3. */
  readonly refusal: null | "item" | "parent";
}

/**
 * Rules 1-3 for one item. Throws 404 when the caller cannot read the transformation or the item does not exist in it;
 * otherwise returns the decision (nothing is thrown for rules 2 and 3, so each route picks its status).
 */
export async function evidenceReadDecision(
  db: DbOrTx,
  principal: Principal,
  transformationId: string,
  evidenceId: string,
): Promise<EvidenceReadDecision> {
  const target = await requireTransformationRead(db, principal, transformationId);
  const row = await db
    .selectFrom("evidence")
    .selectAll()
    .where("id", "=", evidenceId)
    .where("transformation_id", "=", transformationId)
    .executeTakeFirst();
  if (!row) throw problems.notFound();
  const scope = await readScopeFor(db, principal, "transformation.read");
  if (
    !scope.admits({
      recordType: "evidence",
      recordId: row.id,
      target,
      partyUserIds: [row.owner_user_id, row.created_by],
    })
  )
    return { target, row, refusal: "item" };
  for (const parent of await evidenceParents(db, row.id)) {
    const rec = (await loadSensitiveRecords(db, parent.recordType, [parent.recordId])).get(parent.recordId);
    // A link row's FK keeps its record in the evidence's transformation, so `target` is the record's target.
    if (!rec || !scope.admits({ recordType: rec.recordType, recordId: rec.id, target, partyUserIds: rec.partyUserIds }))
      return { target, row, refusal: "parent" };
  }
  return { target, row, refusal: null };
}

/**
 * The download and preview gate (ADR-0051 §4): 404 for a caller without `transformation.read` or a missing item,
 * 403 `evidence.parent_forbidden` for an in-scope caller not admitted to a sensitive item or a sensitive parent.
 */
export async function requireEvidenceRead(
  db: DbOrTx,
  principal: Principal,
  transformationId: string,
  evidenceId: string,
): Promise<{ target: ResolvedTarget; row: EvidenceRow }> {
  const decision = await evidenceReadDecision(db, principal, transformationId, evidenceId);
  if (decision.refusal !== null)
    throw evidenceParentForbidden().withDenial({
      ...denialOf("transformation.read", decision.target),
      recordType: "evidence",
      recordId: evidenceId,
    });
  return { target: decision.target, row: decision.row };
}

/**
 * Rule 3 as SQL over an evidence row, for lists (ADR-0051 §1, §4): true when no linked benefit or business case is
 * refused to the principal by the §2 sensitivity clause. Pair it with `ReadScope.predicate` (rules 1 and 2).
 */
export async function evidenceParentsAdmittedSql(
export type EvidenceBody = AsyncIterable<Uint8Array | string> | Uint8Array;

/**
 * The port both adapters implement (ADR-0010, ADR-0054 §2: unchanged in P6): `stores/filesystem.ts` and `stores/s3.ts`,
 * each proven by the one contract suite `stores/contract.ts`. No method returns, and no adapter creates, a URL: never a
 * public or pre-signed URL and never an ACL; every byte goes through the API route that authorizes the parent record.
 */
export interface EvidenceStore {
  /** `receive` + `finalise` in one call (tests and tools; the upload route uses the two steps, T-DG2-BE17). */
  put(key: string, body: EvidenceBody, maxBytes: number): Promise<StoredObject>;
  /**
   * T-DG2-BE17 step 1: streams `body` into the key's TEMPORARY object (never readable through `get`), computing the
   * SHA-256 over the raw bytes and enforcing `maxBytes` while streaming, and makes it durable (fsync). On any failure
   * (too large, client abort, I/O error) the temporary object is removed and the error is rethrown. The upload route
   * calls it while holding NO database connection or transaction.
   */
  receive(key: string, body: EvidenceBody, maxBytes: number): Promise<StoredObject>;
  /** Step 2: makes a received object readable under its key (atomic rename of the temporary object). */
  finalise(key: string): Promise<void>;
  get(key: string): Promise<AsyncIterable<Uint8Array>>;
  head(key: string): Promise<{ size: number } | null>;
  /**
   * Removes an object that never became committed metadata (failed upload): the final object AND a temporary one
   * that was received but not finalised. Idempotent. Retention deletes are P6.
   */
  discardUncommitted(key: string): Promise<void>;
  /**
   * T-DG2-BE18A (F-DG2-460): removes temporary objects last written more than `olderThanMs` ago (see
   * STALE_TEMPORARY_AGE_MS), calling `onRemoved` for each. Never removes a final (committed or committable) object.
   */
  sweepStaleTemporaries(olderThanMs: number, onRemoved: (removed: RemovedTemporary) => void): Promise<SweepResult>;
}

