    if (refusal === "item")
      throw problems
        .notFound()
        .withDenial({ ...denialOf("transformation.read", target), recordType: "evidence", recordId: row.id });
    if (refusal === "parent")
      throw evidenceParentForbidden().withDenial({
        ...denialOf("transformation.read", target),
        recordType: "evidence",
        recordId: row.id,
      });
