  });
}

function registerContentRoutes(app: FastifyInstance, db: Db, store: EvidenceStore): void {
  app.get(`${ITEM}/content`, { config: { access: { permission: "transformation.read" } } }, async (request, reply) => {
    const { transformationId, evidenceId } = parse(itemParams, request.params, "params");
    // P6 (T-DG6-BE-C; ADR-0051 §4): the item's and its parents' authorization; 404 out of scope, 403
    // evidence.parent_forbidden for an in-scope caller not admitted to a sensitive item or sensitive parent.
    await requireEvidenceRead(db, principalOf(request), transformationId, evidenceId);
    const content = await db
      .selectFrom("evidence as e")
      .innerJoin("evidence_content as c", (j) =>
        j.onRef("c.id", "=", "e.current_content_id").onRef("c.evidence_id", "=", "e.id"),
      )
      .select(["c.storage_key", "c.file_name", "c.sha256", "c.size_bytes"])
      .where("e.id", "=", evidenceId)
      .where("e.transformation_id", "=", transformationId)
      .executeTakeFirst();
    if (!content) throw problems.notFound();
    let stream: AsyncIterable<Uint8Array>;
    try {
      stream = await store.get(content.storage_key);
    } catch (err) {
      throw storeProblem(err) ?? problems.notFound();
    }
    return reply
      .code(200)
      .header("Content-Type", "application/octet-stream")
      .header("Content-Disposition", contentDisposition(content.file_name))
      .header("X-Content-Type-Options", "nosniff")
      .header("Cache-Control", "private, no-store")
      .header("Digest", `sha-256=${Buffer.from(content.sha256, "hex").toString("base64")}`)
      .send(stream);
  });

  // F-DG2-320: the contract declares only application/octet-stream for this operation.
  // T-DG2-BE17 (F-DG2-411): NO client I/O while a pooled connection or a transaction is held. Three phases:
  //   1. preconditions in a short transaction, COMMITTED before the body is read (authorization, the item, If-Match,
  //      the file name, the body's form); every refusal here is answered before a byte of the body is consumed;
  //   2. the body is received into the store's TEMPORARY object (size limit and SHA-256 while streaming) holding no
  //      connection: a slow or stalled client costs a socket and a file handle, never database capacity;
  //   3. a short write transaction: authorization again AT COMMIT TIME (T-DG2-BE18, F-DG2-440: the session is
  //      re-resolved and the grants reloaded inside this transaction, so a logout, session revocation or expiry while
  //      the body streamed is 401 and a revoked grant is 403, audited as a denied mutation; never the request-start
  //      snapshot), the row lock, If-Match re-checked against the LOCKED version
  //      (a concurrent edit during the upload is the declared 409 version_conflict), the content row, the item update
  //      and the audit event; the object is finalised (atomic rename, local I/O only) as the last step before COMMIT,
  //      as before BE17, so a committed content row never points at a missing object.

