  const lines = [
    hit.code === null ? null : `code: ${hit.code}`,
    `title: ${hit.title}`,
    hit.recordStatus === null ? null : `status: ${hit.recordStatus}`,
    hit.summary === null ? null : `summary: ${hit.summary}`,
    excerpt === null ? null : `document text (quoted): ${excerpt}`,
